  return authFetch<ReviewState>(`/decisions/${runId}/takeover`, {
    method: "POST",
    body: JSON.stringify({ reason }),
  });
}

export function releaseReview(runId: string): Promise<ReviewState> {
  return authFetch<ReviewState>(`/decisions/${runId}/release`, { method: "POST" });
}

